PROGRAM motor_interlock
VAR
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
    Motor : BOOL;
    MotorLatch : BOOL;
    EmergencyStopTimer : TON;
END_VAR

// Check if emergency stop is activated
IF NOT EStop THEN
    // If emergency stop is activated, immediately de-energize the motor
    Motor := FALSE;
    // Reset the motor latch
    MotorLatch := FALSE;
    // Reset the emergency stop timer
    EmergencyStopTimer(IN := FALSE);
ELSE
    // If emergency stop is not activated, check the start and stop buttons
    IF Start AND NOT Stop AND NOT MotorLatch THEN
        // If start button is pressed and stop button is not pressed and motor is not latched, latch the motor
        MotorLatch := TRUE;
    ELSIF Stop OR EmergencyStopTimer.Q THEN
        // If stop button is pressed or emergency stop timer has timed out, unlatch the motor
        MotorLatch := FALSE;
    END_IF;

    // Set the motor output based on the motor latch state
    Motor := MotorLatch;
END_IF;

// Start the emergency stop timer if it is not already running
IF NOT EmergencyStopTimer.Q THEN
    EmergencyStopTimer(IN := TRUE, PT := T#5s);
END_IF;
END_PROGRAM

