PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorATimer : TON;
    DoorBTimer : TON;
    OpenDoorA : BOOL;
    OpenDoorB : BOOL;
END_VAR

// Initialize timers
DoorATimer(IN := FALSE, PT := T#0s);
DoorBTimer(IN := FALSE, PT := T#0s);

// Determine if either door should open based on commands
IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    OpenDoorA := TRUE;
    OpenDoorB := FALSE;
ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
    OpenDoorA := FALSE;
    OpenDoorB := TRUE;
ELSE
    OpenDoorA := FALSE;
    OpenDoorB := FALSE;
END_IF;

// Update door states using timers
IF OpenDoorA THEN
    DoorATimer(IN := TRUE, PT := T#0s);
    DoorA := DoorATimer.Q;
    DoorB := FALSE;
ELSE
    DoorATimer(IN := FALSE, PT := T#0s);
    DoorA := FALSE;
END_IF;

IF OpenDoorB THEN
    DoorBTimer(IN := TRUE, PT := T#0s);
    DoorB := DoorBTimer.Q;
    DoorA := FALSE;
ELSE
    DoorBTimer(IN := FALSE, PT := T#0s);
    DoorB := FALSE;
END_IF;

END_PROGRAM

