    IF StartTimer.Q THEN
        IF GuardClosed AND NOT Fault THEN
            ConveyorRunning := TRUE;
        END_IF
    END_IF
END_IF;

// Stop button press or fault detection
IF StopPB OR Fault THEN
    ConveyorRunning := FALSE;
END_IF;

// Guard open detection
IF NOT GuardClosed THEN
    ConveyorRunning := FALSE;
END_IF;

// Latch conveyor state
Conveyor := ConveyorRunning;

END_PROGRAM

