PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TON_NS_G, TON_NS_Y, TON_NS_R : TON;
    TON_EW_G, TON_EW_Y, TON_EW_R : TON;
    PT_GREEN, PT_YELLOW, PT_ALLRED : TIME := T#2s, T#1s, T#1s;
END_VAR

// Initialize timers
TON_NS_G(IN := TRUE, PT := PT_GREEN);
TON_NS_Y(IN := FALSE, PT := PT_YELLOW);
TON_NS_R(IN := FALSE, PT := PT_ALLRED);

TON_EW_G(IN := FALSE, PT := PT_GREEN);
TON_EW_Y(IN := FALSE, PT := PT_YELLOW);
TON_EW_R(IN := FALSE, PT := PT_ALLRED);

// Main loop
CASE State OF
    0 :
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TON_NS_G(IN := TRUE, PT := PT_GREEN);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
        IF TON_NS_G.Q THEN
            State := 1;
        END_IF;

    1 :
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TON_NS_Y(IN := TRUE, PT := PT_YELLOW);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
        IF TON_NS_Y.Q THEN
            State := 2;
        END_IF;

    2 :
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
        IF TON_NS_R.Q THEN
            State := 3;
        END_IF;

    3 :
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        TON_EW_G(IN := TRUE, PT := PT_GREEN);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        IF TON_EW_G.Q THEN
            State := 4;
        END_IF;

    4 :
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        TON_EW_Y(IN := TRUE, PT := PT_YELLOW);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        IF TON_EW_Y.Q THEN
            State := 5;
        END_IF;

    5 :
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        IF TON_EW_R.Q THEN
            State := 0;
        END_IF;
END_CASE

END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TNS_G, TEW_G, TNR, TWR : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

TNS_G(IN := State = 0 OR State = 3, PT := PT_GREEN);
TEW_G(IN := State = 3 OR State = 0, PT := PT_GREEN);
TNR(IN := State IN {0, 1, 3, 4}, PT := PT_RED);
TWR(IN := State IN {1, 2, 4, 5}, PT := PT_RED);

CASE State OF
    0:
        NS_G := TNS_G.Q;
        NS_Y := FALSE;
        NS_R := TNR.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        NS_G := FALSE;
        NS_Y := TNS_G.Q;
        NS_R := TNR.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TNR.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TNR.Q;
        EW_G := TEW_G.Q;
        EW_Y := FALSE;
        EW_R := TWR.Q;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TNR.Q;
        EW_G := FALSE;
        EW_Y := TEW_G.Q;
        EW_R := TWR.Q;
    5:
