        DownTimer(IN := TRUE, PT := T#5s);
    ELSIF State = 1 AND AtTop THEN
        MotorUp := FALSE;
        MotorDown := FALSE;
        State := 2;
    ELSIF State = 3 AND AtBottom THEN
        MotorUp := FALSE;
        MotorDown := FALSE;
        State := 0;
    ELSE
        MotorUp := FALSE;
        MotorDown := FALSE;
    END_IF;

    // Check timers
    IF UpTimer.Q THEN
        State := 2;
        UpTimer(IN := FALSE);
    END_IF;

    IF DownTimer.Q THEN
        State := 0;
        DownTimer(IN := FALSE);
    END_IF;

    // Ensure motors do not run together
    IF MotorUp AND MotorDown THEN
        MotorUp := FALSE;
        MotorDown := FALSE;
    END_IF;

    // Wait for next cycle
    SLEEP(100ms);
END_WHILE;

END_PROGRAM

