PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    FillTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0; // Emergency Stop forces Idle
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: // Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
                FillTimer(IN := TRUE, PT := T#1s);
            ELSE
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;

        1: // Fill
            IF Level >= LVL_HIGH OR NOT StartBatch THEN
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;

        2: // Heat
            IF Temp >= TEMP_SET OR NOT StartBatch THEN
                State := 3;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;

        3: // React
            IF NOT StartBatch THEN
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
            IF FillTimer.Q THEN
                FillTimer(IN := FALSE);
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;

        4: // Drain
            IF Level <= LVL_LOW OR NOT StartBatch THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
    END_CASE;
END_IF;

// Safety Conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

