        DrainValve := FALSE;

        IF Temp >= TEMP_SET THEN
            THeat(IN := TRUE, PT := T#1s);
            IF THeat.Q THEN
                State := 3;
                THeat(IN := FALSE);
            END_IF;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        TReact(IN := TRUE, PT := PT_REACT);
        IF TReact.Q THEN
            State := 4;
            TReact(IN := FALSE);
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;

    ELSE
        State := 0; // Default to Idle if in an invalid state
END_CASE;

// Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

