    DrainTimer : TON;
END_VAR

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    FillTimer(IN := FALSE);
    DrainTimer(IN := FALSE);
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: -- Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH THEN
            State := 2;
            FillTimer(IN := FALSE);
        ELSE
            FillTimer(IN := TRUE, PT := T#1s); -- Assuming 1 second interval for simplicity
        END_IF;
    2: -- Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET THEN
            State := 3;
            DrainTimer(IN := FALSE);
        END_IF;
    3: -- React
        Heater := TRUE;
        Agitator := TRUE;
        IF DrainTimer(Q) OR Level <= LVL_LOW THEN
            State := 4;
            DrainTimer(IN := FALSE);
        ELSE
            DrainTimer(IN := TRUE, PT := PT_REACT);
        END_IF;
    4: -- Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;
END_CASE;
END_PROGRAM

