        ELSE
            ReactTimer(IN := TRUE, PT := PT_REACT);
            IF ReactTimer.Q THEN
                State := 4;
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;
        END_IF;

    4: // Drain
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
            DrainValve := FALSE;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

// Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT (Level >= LIQ_MIN) AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

