PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
    HIGH_LEVEL : INT := 90;
    LOW_LEVEL : INT := 10;
END_VAR

FillTimer(IN := Pump AND NOT EStop, PT := T#5s);
DrainTimer(IN := Valve AND NOT EStop, PT := T#5s);

CASE State OF
    0: -- Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND Level < HIGH_LEVEL AND EStop THEN
            State := 1;
        END_IF;

    1: -- Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= HIGH_LEVEL OR NOT EStop THEN
            State := 2;
        END_IF;

    2: -- Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= LOW_LEVEL OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

-- Safety conditions
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Pump AND Level >= HIGH_LEVEL THEN
    Pump := FALSE;
END_IF;

IF Valve AND Level <= LOW_LEVEL THEN
    Valve := FALSE;
END_IF;

END_PROGRAM

