                Pump := FALSE;
                Valve := TRUE;
            END_IF;

        2: -- Draining
            IF Level <= 10 THEN
                State := 0;
                Pump := FALSE;
                Valve := FALSE;
            END_IF;
    END_CASE;
END_IF;

