PROGRAM tank_cycle
VAR
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
    Pump : BOOL;
    Valve : BOOL;
    State : INT;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

// Initialize State to Idle
State := 0;

WHILE TRUE DO
    CASE State OF
        0: // Idle
            Pump := FALSE;
            Valve := FALSE;
            IF StartCycle AND NOT EStop AND Level < 90 THEN
                State := 1;
                FillTimer(IN := TRUE, PT := T#10s);
            END_IF;

        1: // Filling
            Pump := TRUE;
            Valve := FALSE;
            IF Level >= 90 OR EStop THEN
                State := 2;
                DrainTimer(IN := TRUE, PT := T#10s);
            END_IF;

        2: // Draining
            Pump := FALSE;
            Valve := TRUE;
            IF Level <= 10 OR EStop THEN
                State := 0;
                FillTimer(IN := TRUE, PT := T#10s);
            END_IF;
    END_CASE;
END_WHILE;
END_PROGRAM

PROGRAM tank_cycle
VAR
    State : INT;
    Pump : BOOL;
    Valve : BOOL;
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR CONSTANT
    HIGH : INT := 90;
    LOW : INT := 10;
END_VAR

VAR
    FillTimer : TON;
END_VAR

State := State;

IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF

CASE State OF
    0: -- Idle
        IF StartCycle AND (Level < HIGH) THEN
            State := 1;
            Pump := TRUE;
            Valve := FALSE;
        END_IF;
    1: -- Filling
        IF Level >= HIGH THEN
            State := 2;
            Pump := FALSE;
            Valve := TRUE;
        END_IF;
    2: -- Draining
        IF Level <= LOW THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        END_IF;
END_CASE

-- Safety checks
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF

IF Level >= HIGH THEN
    Pump := FALSE;
END_IF

IF Level <= LOW THEN
    Valve := FALSE;
END_IF

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
    HighLevel : CONST INT := 90;
    LowLevel : CONST INT := 10;
END_VAR

IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
    FillTimer(IN := FALSE);
    DrainTimer(IN := FALSE);
ELSIF NOT EStop THEN
    CASE State OF
        0:  // Idle
            IF StartCycle AND Level < HighLevel THEN
                State := 1;
                Pump := TRUE;
                Valve := FALSE;
                FillTimer(IN := TRUE, PT := T#5s);
            ELSE
                Pump := FALSE;
                Valve := FALSE;
            END_IF;

        1:  // Filling
            IF Level >= HighLevel THEN
                State := 2;
                Pump := FALSE;
                Valve := TRUE;
                DrainTimer(IN := TRUE, PT := T#5s);
            END_IF;

        2:  // Draining
            IF Level <= LowLevel THEN
                State := 0;
                Pump := FALSE;
                Valve := FALSE;
            END_IF;
    END_CASE;
END_IF;

// Safety checks
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= HighLevel AND Pump THEN
    Pump := FALSE;
END_IF;

IF Level <= LowLevel AND Valve THEN
    Valve := FALSE;
END_IF;

END_PROGRAM

