PROGRAM tank_cycle
VAR
    State : INT := 0;
    Pump : BOOL := FALSE;
    Valve : BOOL := FALSE;
    HighLevel : INT := 90;
    LowLevel : INT := 10;
    EStopTimer : TON;
END_VAR

EStopTimer(IN := NOT EStop, PT := T#0s);

CASE State OF
    0:  // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND Level < HighLevel THEN
            State := 1;
        END_IF;

    1:  // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= HighLevel OR EStopTimer.Q THEN
            State := 2;
        END_IF;

    2:  // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= LowLevel OR EStopTimer.Q THEN
            State := 0;
        END_IF;
END_CASE

// Safety checks
IF Pump AND Valve THEN
    State := 0;  // Force Idle if both pump and valve are on
END_IF;

IF Pump AND Level >= HighLevel THEN
    State := 0;  // Force Idle if pump is on at or above high level
END_IF;

IF Valve AND Level <= LowLevel THEN
    State := 0;  // Force Idle if valve is open at or below low level
END_IF;
END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

CONSTANT
    HIGH : INT := 90;
    LOW : INT := 10;
END_CONSTANT

// Safety conditions
ASSERT NOT (Pump AND Valve);
ASSERT NOT (Level >= HIGH AND Pump);
ASSERT NOT (Level <= LOW AND Valve);

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND Level < HIGH THEN
            State := 1;
            FillTimer(IN := TRUE, PT := T#5s);
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF FillTimer.Q OR Level >= HIGH THEN
            State := 2;
            DrainTimer(IN := TRUE, PT := T#5s);
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF DrainTimer.Q OR Level <= LOW THEN
            State := 0;
        END_IF;
END_CASE

// Emergency Stop handling
IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

END_PROGRAM

