            State := 0;
        ELSIF T1.Q THEN
            State := 2;
        END_IF;

    2:
        C1 := TRUE;
        C2 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

