PROGRAM burner
VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
    Fan : BOOL := FALSE;
    Fuel : BOOL := FALSE;
    Ignition : BOOL := FALSE;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0: // Off
            IF StartPB AND EStop THEN
                State := 1;
                PurgeTimer(IN := TRUE, PT := T#3s);
                Fan := TRUE;
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;

        1: // Pre-Purge
            IF PurgeTimer.Q THEN
                State := 2;
                IgnitionTimer(IN := TRUE, PT := T#2s);
                Fan := TRUE;
                Fuel := TRUE;
                Ignition := TRUE;
            END_IF;

        2: // Ignition Trial
            IF IgnitionTimer.Q THEN
                IF Flame THEN
                    State := 3;
                    Fan := TRUE;
                    Fuel := TRUE;
                    Ignition := FALSE;
                ELSE
                    State := 0;
                    Fan := FALSE;
                    Fuel := FALSE;
                    Ignition := FALSE;
                END_IF;
            END_IF;

        3: // Run
            IF NOT Flame THEN
                State := 0;
                Fan := FALSE;
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;
    END_CASE;
END_IF;

IF StopPB OR NOT EStop THEN
    State := 0;
    Fan := FALSE;
    Fuel := FALSE;
    Ignition := FALSE;
END_IF;

// Safety conditions
IF Fuel THEN
    Fan := TRUE;
END_IF;

IF Ignition THEN
    Fuel := TRUE;
END_IF;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
