PurgeTimer(IN := Fan AND NOT EStop, PT := PT_PURGE);
IgnitionTimer(IN := Fan AND Fuel AND NOT EStop, PT := PT_IGN);

CASE State OF
    0:  // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1:  // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;

    2:  // Ignition trial
        Fan := TRUE;
