        Ignition := TRUE;
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;

    3:  // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM burner
VAR
    State : INT;
    StatePrePurge : TON;
    StateIgnitionTrial : TON;
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR

// Initialize state to Off
State := 0;

// Check if StartPB is pressed and system is healthy
IF StartPB AND NOT EStop THEN
    CASE State OF
        0: // Off
            IF NOT StopPB AND NOT EStop THEN
                State := 1;
                StatePrePurge(IN := TRUE, PT := T#3s);
                Fan := FALSE;
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;

        1: // Pre-Purge
            IF StatePrePurge.Q THEN
                State := 2;
                StateIgnitionTrial(IN := TRUE, PT := T#2s);
                Fan := TRUE;
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;

        2: // Ignition Trial
            IF StateIgnitionTrial.Q THEN
                IF Flame THEN
                    State := 3;
                    Fan := TRUE;
                    Fuel := TRUE;
                    Ignition := FALSE;
                ELSE
                    State := 0;
                    Fan := FALSE;
                    Fuel := FALSE;
                    Ignition := FALSE;
                END_IF;
            END_IF;

        3: // Run
            IF NOT Flame OR StopPB OR NOT EStop THEN
                State := 0;
                Fan := FALSE;
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;

    END_CASE;
END_IF;

// Ensure safety conditions are met
IF State = 2 OR State = 3 THEN
    Fan := TRUE;
END_IF;
IF State = 3 THEN
    Fuel := TRUE;
    Ignition := FALSE;
END_IF;
IF State <> 2 THEN
    Ignition := FALSE;
END_IF;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR

VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR

VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

VAR_CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

Fan := FALSE;
Fuel := FALSE;
Ignition := FALSE;

CASE State OF
    0: // Off
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1: // Pre-purge
        PurgeTimer(IN := TRUE, PT := PT_PURGE);
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2: // Ignition trial
        IgnitionTimer(IN := TRUE, PT := PT_IGN);
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
