PROGRAM burner
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

// Logic for starting the burner
IF StartPB AND NOT EStop THEN
    CASE State OF
        0: // Off
            IF NOT StopPB THEN
                State := 1; // Move to Pre-purge
            END_IF;
        1: // Pre-purge
            Fan := TRUE;
            PurgeTimer(IN := TRUE, PT := T#3s);
            IF PurgeTimer.Q THEN
                State := 2; // Move to Ignition trial
                PurgeTimer(IN := FALSE);
            END_IF;
        2: // Ignition trial
            Fan := TRUE;
            Fuel := TRUE;
            Ignition := TRUE;
            IgnitionTimer(IN := TRUE, PT := T#2s);
            IF IgnitionTimer.Q AND Flame THEN
                State := 3; // Move to Run
                IgnitionTimer(IN := FALSE);
            ELSEIF IgnitionTimer.Q AND NOT Flame THEN
                State := 0; // Return to Off due to failed ignition
                IgnitionTimer(IN := FALSE);
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;
        3: // Run
            Fan := TRUE;
            Fuel := TRUE;
            Ignition := FALSE;
            IF NOT Flame OR StopPB OR NOT EStop THEN
                State := 0; // Return to Off
                Fuel := FALSE;
                Ignition := FALSE;
            END_IF;
    END_CASE;
END_IF;

// Safety checks
IF NOT Fan AND Fuel THEN
    Fuel := FALSE;
END_IF;

IF NOT Ignition AND Fuel THEN
    Ignition := FALSE;
END_IF;

END_PROGRAM

