VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    DemandTimer : TON;
END_VAR

IF NOT EStop THEN
    // Emergency stop is active, stop both pumps
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Check for demand start or change
    IF Demand AND NOT PrevDemand THEN
        // Demand has started or changed from previous cycle
        DemandTimer(IN := TRUE, PT := T#0s);
    ELSE
        DemandTimer(IN := FALSE);
    END_IF;

    // Check if demand has ended (falling edge)
    IF NOT Demand AND PrevDemand THEN
        // Demand has ended, switch lead pump
        Lead := 1 - Lead; // Toggle between 0 and 1
    END_IF;

    // Update previous demand state
    PrevDemand := Demand;

    // Assign pumps based on lead state and demand
    IF Demand AND NOT DemandTimer.Q THEN
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
